local SettingRefBase = require('Game.Setting.SettingRefBase')
local base = SettingRefBase
local ParseUtils = CS.ParseUtils

---@class ChaoticRecallNodeVo
local ChaoticRecallNodeVo = Class("ChaoticRecallNodeVo", SettingRefBase)

---__int
function ChaoticRecallNodeVo:__init()
    self.id = nil              --节点id(首位1=固定，2=循环，其次是3位groupid，最后是节点序号）
    self.groupId = nil              --组id
    self.place = nil              --节点序号
    self.name = nil              --名称
    self.unlockPlace = nil              --解锁条件值（填充为0，固定为前置节点解锁）
    self.levelList = nil              --关卡列表
    self.fristRewards = nil              --首次通关掉落
    self.fristRewardsNum = nil              --掉落数量
    self.status = nil              --状态
    self.starCondition = nil
    self.starConditionNum = nil
    self.starConditionRound = nil
    self.rewards = nil
    self.hardLevels = nil
    self.hardRewards = nil
end

---FillVo
---@param row TableML.TableFileRow
function ChaoticRecallNodeVo:FillVo(row)
    base.FillVo(self,row)
    self.id = parse_number(row, "id")
    self.groupId = parse_number(row, "groupId")
    self.place = parse_number(row, "place")
    self.name = ParseUtils.ParseLocalizeText(row, "name")
    self.unlockPlace = parse_string(row, "unlockPlace")
    self.levelList = parse_strings(parse_string(row, "levelList"),";")
    local condition = parse_string(row, "starCondition")
    if not string.isEmpty(condition) then
        self.starCondition = parse_strings(condition,";")
    end
    
    local starConditionNum = parse_string(row, "starConditionNum")
    if not string.isEmpty(starConditionNum) then
        self.starConditionNum = parse_strings(starConditionNum,";")
    end
    
    local starConditionRound = parse_string(row, "starConditionRound")
    if not string.isEmpty(starConditionRound) then
        self.starConditionRound = parse_strings(starConditionRound,";")
    end
    
    self.fristRewards = parse_string(row, "fristRewards")
    self.fristRewardsNum = parse_string(row, "fristRewardsNum")
    self.rewards = parse_rewards(self.fristRewards,self.fristRewardsNum)
    self.status = parse_number(row, "status")

    for i = 1, 2 do
        local level = parse_string(row, "hardLevel"..i)
        if not isNull(level) and level ~= "" then
            level = parse_strings(level,";")
            if isNull(self.hardLevels) then
                self.hardLevels = {}
            end
            self.hardLevels[i] = level
        end

        local rewards = parse_rewards(parse_string(row, "hardRewards"..i),parse_string(row, "hardRewardsNum"..i))
        if not isNull(rewards) and table.count(rewards) > 0 then
            if isNull(self.hardRewards) then
                self.hardRewards = {}
            end
            self.hardRewards[i] = rewards
        end
    end

    -- 页签表里会标记是默认模式还是挑战模式
    local groupVo = CfUtils.GetCfVo(AutoIds.IdSetting6114,"ChaoticRecallTagVo", self.groupId)
    local isChallengeGroup = groupVo.groupType == 1

    -- 加载节点表时，写入关卡表需要的信息
    for i, questId in ipairs(self.levelList) do
        questId = checkNumber(questId)
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting6108,"ChaoticRecallLevelVo",questId)
        if isNotNull(vo) then
            vo.starCondition = parse_string(row, "starCondition")
            vo.starConditionNum = parse_string(row, "starConditionNum")
            vo.starConditionRound = parse_string(row, "starConditionRound")
            vo.nodeTeamCount = #self.levelList
            vo.nodeId = self.id

            -- 挑战模式的最后一个节点标记为boss挑战关卡(因为不知道怎么判断是最后一个节点，所以这里用三星条件是否为空作为替代的判断)
            vo.isBossChallengeQuest = isChallengeGroup and isNull(self.starCondition)
        end
    end
    
    if isNotNull(self.hardLevels) then
        for k, v in ipairs(self.hardLevels) do
            for i, questId in ipairs(v) do
                questId = checkNumber(questId)
                local vo = CfUtils.GetCfVo(AutoIds.IdSetting6108,"ChaoticRecallLevelVo",questId)
                if isNotNull(vo) then
                    vo.starCondition = parse_string(row, "starCondition")
                    vo.starConditionNum = parse_string(row, "starConditionNum")
                    vo.starConditionRound = parse_string(row, "starConditionRound")
                    vo.nodeTeamCount = #self.hardLevels
                    vo.nodeId = self.id
                end
            end
        end
    end
end

function ChaoticRecallNodeVo:__delete()
    self.id = nil
    self.groupId = nil
    self.place = nil
    self.name = nil
    self.unlockPlace = nil
    self.levelList = nil
    self.starCondition = nil
    self.starConditionNum = nil
    self.starConditionRound = nil
    self.fristRewards = nil
    self.fristRewardsNum = nil
    self.rewards = nil
    self.hardLevels = nil
    self.hardRewards = nil
    self.status = nil
end

return ChaoticRecallNodeVo
